package stapel.config

/**
 * How strict the client is. Generated by the scaffold from `stapel.composition.json`; there is no
 * runtime read of the backend's posture.
 */
public enum class Posture {
    /** Local and sample builds: cleartext `http://` to local hosts and body logging are allowed. */
    Prototype,

    /** Shipped builds: every endpoint is `https://`; body logging is refused. */
    Live,
}

/**
 * Where one backend module answers: the URL its API mount is served at
 * (`https://api.example.com/auth/api/v1/`). A monolith gives every module the same origin;
 * microservices give each its own.
 *
 * @property baseUrl absolute `http(s)` URL of the mount; normalized to end with `/`.
 */
public class ServiceEndpoint(baseUrl: String) {
    public val baseUrl: String = baseUrl.trim().let { if (it.endsWith("/")) it else "$it/" }

    init {
        require(this.baseUrl.startsWith("https://") || this.baseUrl.startsWith("http://")) {
            "ServiceEndpoint must be an absolute http(s) URL: $baseUrl"
        }
        require(host.isNotEmpty()) { "ServiceEndpoint has no host: $baseUrl" }
    }

    /** `https` or `http`. */
    public val scheme: String get() = baseUrl.substringBefore("://")

    /** The host, without port. */
    public val host: String
        get() = authority.let { a -> if (a.startsWith("[")) a.substringBefore("]") + "]" else a.substringBefore(":") }

    /** True when the base URL has no path (`https://api.example.com/`). */
    public val isBareOrigin: Boolean get() = baseUrl == "$origin/"

    /** `scheme://host[:port]`, no path. */
    public val origin: String get() = "$scheme://$authority"

    private val authority: String get() = baseUrl.substringAfter("://").substringBefore("/")

    /** Equal when the normalized base URLs are equal. */
    override fun equals(other: Any?): Boolean = other is ServiceEndpoint && other.baseUrl == baseUrl

    /** Consistent with [equals]. */
    override fun hashCode(): Int = baseUrl.hashCode()

    /** The base URL. */
    override fun toString(): String = baseUrl
}

/**
 * One build flavour's backend: the endpoint of every module, the posture and who the client is.
 * The scaffold emits one per flavour; nothing here fetches or parses configuration.
 *
 * Construction fails (IllegalArgumentException, at start, not at the first request) when an
 * endpoint is cleartext `http://` to a host that is not local, or any cleartext endpoint under
 * [Posture.Live].
 *
 * @property name the flavour (`production`, `staging`, `local`).
 * @property posture how strict the client is.
 * @property defaultEndpoint where a module without its own entry answers.
 * @property client who the client is (User-Agent, client hints).
 * @property supportedLocales the locales the app ships, first = fallback.
 */
public class StapelEnvironment(
    public val name: String,
    public val posture: Posture,
    endpoints: Map<String, ServiceEndpoint> = emptyMap(),
    public val defaultEndpoint: ServiceEndpoint? = null,
    public val client: ClientInfo,
    public val supportedLocales: List<String> = listOf("en"),
) {
    private val endpoints: Map<String, ServiceEndpoint> = endpoints.toMap()

    init {
        require(supportedLocales.isNotEmpty()) { "StapelEnvironment '$name' lists no supported locale" }
        (this.endpoints.entries.map { it.key to it.value } + listOfNotNull(defaultEndpoint?.let { "<default>" to it }))
            .forEach { (module, endpoint) -> checkCleartext(module, endpoint) }
    }

    private fun checkCleartext(module: String, endpoint: ServiceEndpoint) {
        if (endpoint.scheme != "http") return
        require(posture == Posture.Prototype) {
            "StapelEnvironment '$name': module '$module' uses cleartext ${endpoint.baseUrl} under Posture.Live; use https"
        }
        require(isLocalHost(endpoint.host)) {
            "StapelEnvironment '$name': cleartext http is allowed only to loopback / private hosts, not ${endpoint.host}"
        }
    }

    /** The modules with an endpoint of their own. */
    public val modules: Set<String> get() = endpoints.keys

    /**
     * Where [module] answers: its own entry, else [defaultEndpoint].
     *
     * @throws IllegalStateException naming the module when neither exists.
     */
    public fun endpoint(module: String): ServiceEndpoint =
        endpoints[module] ?: defaultEndpoint
            ?: throw IllegalStateException("StapelEnvironment '$name' has no endpoint for module '$module' and no default")

    /**
     * The absolute URL of [path] for [module].
     *
     * - A relative path (`sessions/`) is appended to the module's base URL.
     * - A canonical absolute path (`/auth/api/v1/sessions/`, as generated code carries it): when the
     *   endpoint is a bare origin (`https://api.example.com/`, a monolith serving every canonical
     *   mount) the path is kept; when the endpoint has a path of its own
     *   (`https://gw.example.com/identity/`) the mount `/<module>/api/v<N>/` is replaced by it.
     * - Any other absolute path resolves against the origin.
     */
    public fun url(module: String, path: String): String {
        val base = endpoint(module)
        if (!path.startsWith("/")) return base.baseUrl + path
        val mount = CANONICAL_MOUNT.find(path)
        if (mount == null || base.isBareOrigin) return base.origin + path
        return base.baseUrl + path.substring(mount.range.last + 1)
    }

    /** The WebSocket origin of [module]: `https` → `wss`, `http` → `ws`, path dropped. */
    public fun websocketOrigin(module: String): String {
        val base = endpoint(module)
        val scheme = if (base.scheme == "https") "wss" else "ws"
        return base.origin.replaceFirst(base.scheme, scheme)
    }

    /** Debug form without any secret (there are none here). */
    override fun toString(): String = "StapelEnvironment($name, $posture, modules=${endpoints.keys}, default=$defaultEndpoint)"

    /** Holder of [single]. */
    public companion object {
        private val CANONICAL_MOUNT = Regex("""^/[^/]+/api/v\d+/""")

        /** One backend answering every module at [baseUrl]'s origin (a monolith or a gateway). */
        public fun single(name: String, baseUrl: String, posture: Posture, client: ClientInfo): StapelEnvironment =
            StapelEnvironment(name, posture, defaultEndpoint = ServiceEndpoint(baseUrl), client = client)
    }
}

/**
 * True for hosts cleartext may go to under [Posture.Prototype]: loopback, RFC 1918 and link-local
 * addresses, the Android emulator's host alias and `*.local` / `localhost` names.
 */
public fun isLocalHost(host: String): Boolean {
    val h = host.lowercase().removePrefix("[").removeSuffix("]")
    if (h == "localhost" || h.endsWith(".localhost") || h.endsWith(".local")) return true
    if (h == "::1") return true
    val parts = h.split('.').map { it.toIntOrNull() ?: return false }
    if (parts.size != 4 || parts.any { it !in 0..255 }) return false
    val (a, b) = parts
    return a == 127 || a == 10 || (a == 172 && b in 16..31) || (a == 192 && b == 168) || (a == 169 && b == 254)
}
